import {polygon,area} from './geometry.js';
import {allocation} from './racks.js';
import {entranceGeometry} from './entrances.js';
export const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n.toLocaleString(undefined,{maximumFractionDigits:1}),pts=p=>p.map(p=>`${p.x},${p.y}`).join(' ');
export function layoutChart(f){const points=f.shapes.flatMap(polygon);if(!points.length)return '<div class="chartEmpty">No foundation on this floor yet. Create a footprint in Editor.</div>';const minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x)),minY=Math.min(...points.map(p=>p.y)),maxY=Math.max(...points.map(p=>p.y)),pad=Math.max(maxX-minX,maxY-minY)*.08+1,font=Math.max(maxX-minX,maxY-minY)/65;return `<svg class="capacityLayout" role="img" aria-label="${escape(f.label)} capacity layout chart" viewBox="${minX-pad} ${minY-pad} ${maxX-minX+pad*2} ${maxY-minY+pad*2}"><defs><pattern id="overviewHatch" width="${font*.55}" height="${font*.55}" patternUnits="userSpaceOnUse"><path d="M0 ${font*.55} L${font*.55} 0" stroke="#7f8ca8" stroke-width="${font*.05}"/></pattern></defs>${f.shapes.filter(s=>s.layer==='foundation').map(o=>`<polygon points="${pts(polygon(o))}" fill="#e0e2e7" stroke="#adb3bf" stroke-width="${font*.08}"/>`).join('')}${f.sections.map((s,i)=>{const p=polygon(s),a=allocation(s,s.stats),center=p.reduce((q,v)=>({x:q.x+v.x/p.length,y:q.y+v.y/p.length}),{x:0,y:0});return `<g data-capacity-section="${escape(s.id)}"><title>${escape(s.name)}${s.rackPlacement===false?' (reserved non-storage)':''}: ${fmt(s.stats.total)} m²; assigned ${fmt(s.stats.assigned)} m²; unassigned ${fmt(s.stats.unassigned)} m²; unracked ${fmt(s.stats.free)} m²</title><polygon points="${pts(p)}" fill="${s.rackPlacement===false?'#d5d9e1':'white'}" stroke="#aeb5c4" stroke-width="${font*.08}"/>${a.assigned.length?`<polygon points="${pts(a.assigned)}" fill="url(#overviewHatch)"/>`:''}${a.rack.length?`<polygon points="${pts(a.rack)}" fill="none" stroke="#9ba7bd" stroke-width="${font*.07}"/>`:''}${a.assigned.length?`<polygon points="${pts(a.assigned)}" fill="none" stroke="#9ba7bd" stroke-width="${font*.06}"/>`:''}<polygon class="sectionHighlight" points="${pts(p)}" fill="#788cbd" fill-opacity=".16" stroke="#667eb2" stroke-width="2.5" vector-effect="non-scaling-stroke" pointer-events="none"/><text x="${center.x}" y="${center.y}" text-anchor="middle" font-size="${font}" fill="#515e77" font-family="Arial">${i+1}</text></g>`}).join('')}${f.walls.filter(w=>w.enabled).map(w=>`<line x1="${w.a.x}" y1="${w.a.y}" x2="${w.b.x}" y2="${w.b.y}" stroke="#525b6e" stroke-width="${font*.17}"/>`).join('')}${f.entrances.filter(e=>e.anchor).map(e=>{const g=entranceGeometry(e,f.shapes);return g?`<line x1="${g.a.x}" y1="${g.a.y}" x2="${g.b.x}" y2="${g.b.y}" stroke="white" stroke-width="${font*.4}"/><line x1="${g.a.x}" y1="${g.a.y}" x2="${g.b.x}" y2="${g.b.y}" stroke="#8a96ad" stroke-width="${font*.09}" stroke-dasharray="${font*.15} ${font*.1}"/>`:''}).join('')}</svg>`;}
export function table(headers,rows,cls=''){return `<div class="dataScroll"><table class="reportTable ${cls}"><thead><tr>${headers.map(h=>`<th scope="col">${escape(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${escape(typeof v==='number'?fmt(v):v)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="noRows">No data yet.</td></tr>`}</tbody></table></div>`;}
